CREATE TABLE ibexa_content (id INT AUTO_INCREMENT NOT NULL, content_type_id INT DEFAULT 0 NOT NULL, current_version INT DEFAULT NULL, initial_language_id BIGINT DEFAULT 0 NOT NULL, language_mask BIGINT DEFAULT 0 NOT NULL, modified INT DEFAULT 0 NOT NULL, name VARCHAR(255) DEFAULT NULL, owner_id INT DEFAULT 0 NOT NULL, published INT DEFAULT 0 NOT NULL, remote_id VARCHAR(100) DEFAULT NULL, section_id INT DEFAULT 0 NOT NULL, status INT DEFAULT 0, is_hidden TINYINT(1) DEFAULT '0' NOT NULL, INDEX ibexa_content_type_id (content_type_id), INDEX ibexa_content_lmask (language_mask), INDEX ibexa_content_pub (published), INDEX ibexa_content_section (section_id), INDEX ibexa_content_currentversion (current_version), INDEX ibexa_content_owner (owner_id), INDEX ibexa_content_status (status), UNIQUE INDEX ibexa_content_remote_id (remote_id), PRIMARY KEY(id)) DEFAULT CHARACTER SET utf8 COLLATE `utf8_unicode_ci` ENGINE = InnoDB;
